style.css:
/* Set a soft purple background color */
body {
  background-color: #fbe6fc; /* Light purple */
}

/* Change text color to a soft purple */
body, p, h1, h2, h3, h4, h5, h6 {
  color: #806b8a; /* Light purple */
}

/* Add some magical effects to links */
a {
  color: #ad69ff; /* Hot purple */
  text-decoration: underline;
}

/* Change button styles */
button, input[type="button"], input[type="submit"] {
  background-color: #e9b6ff; /* Light purple */
  color: #fff; /* White */
  border: 2px solid #ad69ff; /* Hot purple */
  border-radius: 5px;
  padding: 8px 12px;
  cursor: pointer;
}

/* Add cute hover effect to buttons */
button:hover, input[type="button"]:hover, input[type="submit"]:hover {
  background-color: #e7d4ff; /* Soft purple */
  color: #fff; /* White */
}

/* Add a magical border to images */
img {
  border: 3px solid #fbe6fc; /* Light pink */
  border-radius: 10px;
}

